class Solution {
  public int[] maximumMEX(int[] nums) {
    int n = nums.length;
    int[] sufMex = new int[n + 1];
    boolean[] seen = new boolean[n + 2];
    int mex = 0;
    for (int i = n - 1; i >= 0; i--) {
      if (nums[i] <= n) seen[nums[i]] = true;
      while (seen[mex]) mex++;
      sufMex[i] = mex;
    }
    int[] stamp = new int[n + 2];
    java.util.Arrays.fill(stamp, -1);
    List<Integer> res = new ArrayList<>();
    int start = 0, round = 0;
    while (start < n) {
      int target = sufMex[start], covered = 0, j = start;
      if (target == 0) {
        res.add(0);
        start++;
        continue;
      }
      for (; j < n; j++) {
        int v = nums[j];
        if (v < target && stamp[v] != round) {
          stamp[v] = round;
          covered++;
        }
        if (covered == target) break;
      }
      res.add(target);
      start = j + 1;
      round++;
    }
    int[] ans = new int[res.size()];
    for (int i = 0; i < ans.length; i++) ans[i] = res.get(i);
    return ans;
  }
}
